import sys
from openpyxl import load_workbook

path = "budget.xlsx"

# Load cached values and formula strings separately
wb_values = load_workbook(path, data_only=True)
wb_formulas = load_workbook(path, data_only=False)

for ws in wb_values.worksheets:
    print(f"\n=== Sheet: {ws.title} (dims {ws.dimensions}) ===")
    wsf = wb_formulas[ws.title]
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None:
                f = wsf[cell.coordinate].value
                if isinstance(f, str) and f.startswith("="):
                    print(f"{cell.coordinate}: {cell.value!r}  [formula: {f}]")
                else:
                    print(f"{cell.coordinate}: {cell.value!r}")

import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}
M = NS["m"]


def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group(0)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx - 1  # 0-based


def row_num(ref):
    return int(re.search(r"\d+", ref).group(1))


path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("ZIP entries:")
    for n in names:
        print("  ", n)

    def read_xml(p):
        with z.open(p) as f:
            return ET.fromstring(f.read())

    wb = read_xml("xl/workbook.xml")
    sheets = [(s.get("name"), s.get("sheetId")) for s in wb.findall(f".//{M}sheets/{M}sheet")]
    print("\nSheets:", sheets)

    # Map sheet names to relationship targets
    rels = read_xml("xl/_rels/workbook.xml.rels")
    rel_map = {}
    for rel in rels.findall(f"{NS['r']}Relationship"):
        rel_map[rel.get("Id")] = rel.get("Target")

    # Shared strings
    shared = []
    if "xl/sharedStrings.xml" in names:
        ss = read_xml("xl/sharedStrings.xml")
        for si in ss.findall(f"{M}si"):
            text = "".join(t.text or "" for t in si.iter(f"{M}t"))
            shared.append(text)

    # Map sheet name -> worksheet xml
    sheet_target = {}
    for s in wb.findall(f".//{M}sheets/{M}sheet"):
        rid = s.get(f"{{{NS['r']}}}id")
        target = rel_map.get(rid, "")
        if not target.startswith("xl/"):
            target = "xl/" + target.lstrip("/")
        sheet_target[s.get("name")] = target

    print("\nSheet -> target:", sheet_target)

    for sname, target in sheet_target.items():
        ws = read_xml(target)
        print(f"\n=== Sheet: {sname} ===")
        cells = {}
        for c in ws.iter(f"{M}c"):
            ref = c.get("r")
            t = c.get("t")
            v = c.find(f"{M}v")
            if v is None:
                continue
            val = v.text
            if t == "s":
                val = shared[int(val)]
            elif t == "b":
                val = val == "1"
            elif t == "str":
                pass
            else:
                try:
                    val = float(val)
                except (TypeError, ValueError):
                    pass
            f = c.find(f"{M}f")
            cells[ref] = (val, f.text if f is not None else None)
        # Print in row-major order
        for ref in sorted(cells, key=lambda r: (row_num(r), col_to_idx(r))):
            val, formula = cells[ref]
            extra = f"  [formula: {formula}]" if formula else ""
            print(f"{ref}: {val!r}{extra}")

